/* ? Facebook Liquid Glass Adaptive Mode by Seif Style */

:root {
  --blur: 18px;
  --radius: 18px;
  --shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
  --transition: 0.3s ease-in-out;
}

/* ===== LIGHT MODE ===== */
@media (prefers-color-scheme: light) {
  :root {
    --glass-bg: rgba(255, 255, 255, 0.35);
    --glass-border: rgba(255, 255, 255, 0.45);
    --glass-overlay1: rgba(255, 255, 255, 0.25);
    --glass-overlay2: rgba(180, 200, 255, 0.15);
    --text-color: #111;
  }
}

/* ===== DARK MODE ===== */
@media (prefers-color-scheme: dark) {
  :root {
    --glass-bg: rgba(30, 30, 40, 0.45);
    --glass-border: rgba(255, 255, 255, 0.15);
    --glass-overlay1: rgba(120, 150, 255, 0.08);
    --glass-overlay2: rgba(60, 90, 180, 0.15);
    --text-color: #f5f5f5;
  }
}

/* ===== Base Glass Effect ===== */
header[role="banner"],
div[role="banner"],
div[role="main"],
div[data-pagelet^="FeedUnit_"],
div[role="article"],
[role="complementary"],
aside,
[data-pagelet*="RightRail"],
[role="dialog"],
[aria-label="Menu"],
[role="menu"] {
  background: var(--glass-bg) !important;
  border: 1px solid var(--glass-border) !important;
  backdrop-filter: blur(var(--blur)) saturate(140%) !important;
  -webkit-backdrop-filter: blur(var(--blur)) saturate(140%) !important;
  border-radius: var(--radius) !important;
  box-shadow: var(--shadow) !important;
  transition: background var(--transition), border var(--transition), box-shadow var(--transition);
  position: relative;
  overflow: hidden;
}

/* ===== Animated liquid layer ===== */
@keyframes liquidMotion {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

header[role="banner"]::before,
div[role="main"]::before,
div[data-pagelet^="FeedUnit_"]::before,
div[role="article"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg,
    var(--glass-overlay1),
    var(--glass-overlay2),
    transparent);
  background-size: 200% 200%;
  mix-blend-mode: overlay;
  animation: liquidMotion 12s ease-in-out infinite;
  pointer-events: none;
  border-radius: inherit;
}

/* ===== Hover lift for posts ===== */
div[data-pagelet^="FeedUnit_"]:hover,
div[role="article"]:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.25);
}

/* ===== Header fixes ===== */
header[role="banner"],
div[role="banner"] {
  position: sticky !important;
  top: 0 !important;
  z-index: 9999 !important;
  backdrop-filter: blur(var(--blur)) saturate(140%) !important;
  -webkit-backdrop-filter: blur(var(--blur)) saturate(140%) !important;
}

/* ===== Text clarity ===== */
body, div, span, a, p, h1, h2, h3, h4 {
  color: var(--text-color) !important;
  text-shadow: none !important;
  transition: color var(--transition);
}

body {
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif !important;
}

/* ===== Dialogs & Menus ===== */
[role="dialog"],
[aria-label="Menu"],
[role="menu"] {
  background: var(--glass-bg) !important;
  border: 1px solid var(--glass-border) !important;
  backdrop-filter: blur(var(--blur)) !important;
  -webkit-backdrop-filter: blur(var(--blur)) !important;
}

/* ===== Performance ===== */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
  }
}
